mapper.select:
SELECT a.ANSWER_ID as answerId, a.QUESTION_ID as questionId, a.LAWYER_ID as lawyerId, a.CONTENT as content, a.IS_ADOPTED as isAdopted, a.CREATED_AT as createdAt, a.ADOPTED_AT as adoptedAt, a.UPDATED_AT as updatedAt,
/* 💡 핵심 수정: 변호사의 MEMBER_ID를 가져와야 프론트에서 본인 확인 가능 */ m.MEMBER_ID as memberId, m.NAME as lawyerName, l.OFFICE_NAME as officeName, l.SPECIALTY as specialty,
/* 변호사 활동 지표 */ l.ADOPT_CNT as adoptCnt, (SELECT COUNT(*) FROM TB_ANSWER WHERE LAWYER_ID = l.LAWYER_ID) as answerCnt,
/* 프로필 이미지 */ att.SAVE_PATH as lawyerProfile
FROM TB_ANSWER a JOIN TB_LAWYER l ON a.LAWYER_ID = l.LAWYER_ID JOIN TB_MEMBER m ON l.MEMBER_ID = m.MEMBER_ID LEFT OUTER JOIN TB_ATTACHMENT att ON l.LAWYER_ID = att.REF_ID AND att.REF_TYPE = 'LAWYER' WHERE a.QUESTION_ID = #{questionId} ORDER BY a.IS_ADOPTED DESC, a.CREATED_AT ASC
